INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kann ich kollaborativ Code pflegen ohne Versionskontrolle?', 2, '[{"text": "Nein", "correct": true, "because": "Versionskontrolle koordiniert Änderungen"}, {"text": "Ja", "correct": false, "because": "Ohne Chaos riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit kollaborativer Codepflege?', 3, '[{"text": "Teamarbeit fördern", "correct": true, "because": "Koordiniert Beiträge"}, {"text": "Performance", "correct": false, "because": "Indirekt"}, {"text": "Design", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools helfen bei der kollaborativen Codepflege?', 5, '[{"text": "Git", "correct": true, "because": "Versionskontrolle"}, {"text": "Pull Requests", "correct": true, "because": "Code-Review"}, {"text": "Notepad", "correct": false, "because": "Keine Kollaboration"}, {"text": "E-Mail", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Git verhindert Konflikte. b) Kollaboration braucht Kommunikation.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "a) reduziert, nicht verhindert"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der kollaborativen Codepflege?', 4, '[{"text": "Commits", "correct": false, "because": "Dokumentiert Änderungen"}, {"text": "Branches", "correct": false, "because": "Trennt Arbeiten"}, {"text": "Schriftfarbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Kollaboration ohne Git möglich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Manuell machbar"}, {"text": "Nein", "correct": false, "because": "Git effizienter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature nutze ich für Teamarbeit in Git?', 3, '[{"text": "Branches", "correct": true, "because": "Isoliert Änderungen"}, {"text": "TXT-Dateien", "correct": false, "because": "Keine Kollaboration"}, {"text": "E-Mail", "correct": false, "because": "Unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen kollaborative Codepflege effektiv?', 5, '[{"text": "Klare Kommunikation", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Code-Review", "correct": true, "because": "Sichert Qualität"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Irrelevant"}, {"text": "Lange Meetings", "correct": false, "because": "Zeitverschwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Kollaboration ist nur für große Teams. b) Git ersetzt Kommunikation. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Auch kleine Teams, Git ergänzt"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht korrekt"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für kollaborative Codepflege?', 4, '[{"text": "Versionskontrolle", "correct": false, "because": "Koordiniert Änderungen"}, {"text": "Merge-Strategie", "correct": false, "because": "Löst Konflikte"}, {"text": "Monitorgröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Kollaboration ohne Regeln möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Regeln verhindern Chaos"}, {"text": "Ja", "correct": false, "because": "Risiko für Konflikte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Praktiken sind für kollaborative Codepflege entscheidend?', 4, '[{"text": "Regelmäßige Commits", "correct": true, "because": "Hält Stand aktuell"}, {"text": "Code-Review", "correct": true, "because": "Sichert Qualität"}, {"text": "UI-Design", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Kollaboration ohne Git besser ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Git erleichtert Zusammenarbeit"}, {"text": "Ja", "correct": false, "because": "Manuell ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der kollaborativen Codepflege?', 3, '[{"text": "Koordination", "correct": true, "because": "Synchronisiert Team"}, {"text": "Schnelle Änderungen", "correct": false, "because": "Qualität zählt"}, {"text": "Individuelle Freiheit", "correct": false, "because": "Risiko für Chaos"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Pull Requests fördern Qualität. b) Kollaboration braucht keine Regeln.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) führt zu Chaos"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet kollaborative Codepflege?', 5, '[{"text": "Höhere Qualität", "correct": true, "because": "Durch Reviews"}, {"text": "Schnellere Entwicklung", "correct": true, "because": "Teamarbeit"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Weniger Tests", "correct": false, "because": "Tests bleiben nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der kollaborativen Codepflege unwichtig?', 3, '[{"text": "Commit-Historie", "correct": false, "because": "Zeigt Verlauf"}, {"text": "Teamkommunikation", "correct": false, "because": "Koordiniert Arbeit"}, {"text": "Papierformat", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt Git die Teamarbeit?', 3, '[{"text": "Nein", "correct": true, "because": "Unterstützt sie nur"}, {"text": "Ja", "correct": false, "because": "Teamarbeit zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Kollaboration nur für Code gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Doku etc."}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für kollaborative Codepflege entscheidend?', 4, '[{"text": "Versionskontrolle", "correct": true, "because": "Synchronisiert Änderungen"}, {"text": "Hohe Komplexität", "correct": false, "because": "Verwirrt"}, {"text": "Manuelle Koordination", "correct": false, "because": "Ineffizient"}]');
